package com.aidevos.orchestrator.persistence.postgresql;
import java.util.List; import javax.sql.DataSource; import com.aidevos.orchestrator.validation.security.*; import tools.jackson.databind.ObjectMapper;
final class PostgresSecurityReportRepository implements SecurityReportRepository {private static final String TYPE="security-report";private volatile PostgresDocumentStore store;private final DataSource source;private final ObjectMapper mapper;PostgresSecurityReportRepository(DataSource s,ObjectMapper m){source=s;mapper=m;}PostgresSecurityReportRepository(PostgresDocumentStore s){store=s;source=null;mapper=null;}private PostgresDocumentStore store(){if(store==null)synchronized(this){if(store==null)store=new PostgresDocumentStore(source,mapper);}return store;}public void save(SecurityReport r){store().put(TYPE,r.getReportId(),r,r.getValidationRunId());}public SecurityReport get(String id){return store().get(TYPE,id,SecurityReport.class);}public List<SecurityReport> findByValidationRunId(String id){return store().allBySecondary(TYPE,id,SecurityReport.class);}}
